<?php $page_title='Create Bill';require_once __DIR__.'/../includes/header.php';$p=$pdo->query("SELECT id,name FROM patients ORDER BY name")->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){$no='INV'.date('ymdHis').rand(10,99);$pdo->prepare("INSERT INTO bills(invoice_no,patient_id,description,amount,method,status) VALUES(?,?,?,?,?,?)")->execute([$no,$_POST['patient_id'],$_POST['description'],$_POST['amount'],$_POST['method'],$_POST['status']]);header('Location:index.php');exit;}?><h2>Create Bill</h2><div class="card p-4 mt-3"><form method="post"><div class="row g-3"><div class="col-md-6"><label>Patient</label><select name="patient_id" class="form-select"><?php foreach($p as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label>Amount</label><input name="amount" type="number" step=".01" class="form-control" required></div><div class="col-md-6"><label>Description</label><input name="description" class="form-control" required></div><div class="col-md-3"><label>Method</label><select name="method" class="form-select"><option>Cash</option><option>Card</option><option>Bank Transfer</option><option>Mobile Money</option></select></div><div class="col-md-3"><label>Status</label><select name="status" class="form-select"><option>paid</option><option>pending</option></select></div></div><button class="btn btn-success mt-3">Save Bill</button></form></div><?php require_once __DIR__.'/../includes/footer.php';?>